// ── Segurança do webhook ────────────────────────────────────────────────────
// 1) Assinatura: com WHATSAPP_APP_SECRET definido, só passa o POST assinado pela Meta
//    (X-Hub-Signature-256 = HMAC-SHA256 do corpo cru com o app secret). Precisa do corpo cru
//    (opção rawBody do nó Webhook) e de NODE_FUNCTION_ALLOW_BUILTIN=crypto no n8n.
// 2) Repetição: a Meta reenvia a mesma mensagem quando acha que não recebemos; o id da mensagem
//    fica guardado por 24 h e a segunda entrega é ignorada (senão o cliente recebe tudo em dobro).
const appSecret = $env.WHATSAPP_APP_SECRET || '';
const incoming = $input.first();
const isMetaPayload = !!(incoming.json.body || {}).entry;
// Formato já extraído (01-whatsapp-receiver) não tem assinatura da Meta: com o app secret ligado,
// só entra com o token interno, senão qualquer um mandaria mensagem em nome de um cliente.
if (appSecret && !isMetaPayload) {
  const internalToken = $env.ORDER_HUB_N8N_INTERNAL_TOKEN || '';
  const sentToken = String((incoming.json.headers || {})['x-internal-token'] || '');
  if (!internalToken || sentToken !== internalToken) {
    console.log('[webhook] POST interno sem token descartado');
    return [];
  }
}
if (appSecret && isMetaPayload) {
  const headers = incoming.json.headers || {};
  const received = String(headers['x-hub-signature-256'] || '');
  let valid = false;
  try {
    const crypto = require('crypto');
    const rawBody = await this.helpers.getBinaryDataBuffer(0, 'data');
    const expected = 'sha256=' + crypto.createHmac('sha256', appSecret).update(rawBody).digest('hex');
    valid = received.length === expected.length
      && crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));
  } catch (error) {
    console.log('[webhook] não foi possível conferir a assinatura da Meta:', error.message);
  }
  if (!valid) {
    console.log('[webhook] POST sem assinatura válida da Meta descartado');
    return [];
  }
}

const seenMessageId = (() => {
  const messageId = (incoming.json.body || {}).entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.id;
  if (!messageId) return false;
  const store = $getWorkflowStaticData('global');
  const seen = store.seenMessageIds || {};
  const now = Date.now();
  const ttl = 24 * 60 * 60 * 1000;
  for (const [id, at] of Object.entries(seen)) if (now - at > ttl) delete seen[id];
  if (seen[messageId]) return true;
  seen[messageId] = now;
  // Teto para o dado do workflow não crescer sem limite.
  const ids = Object.keys(seen);
  if (ids.length > 2000) for (const id of ids.slice(0, ids.length - 2000)) delete seen[id];
  store.seenMessageIds = seen;
  return false;
})();
if (seenMessageId) {
  console.log('[webhook] mensagem repetida da Meta ignorada');
  return [];
}

// Input from 01-whatsapp-receiver via webhook (body-wrapped) or direct
const raw = $json.body || $json;

// Detect source: if has entry[] it's direct Meta webhook, otherwise it's pre-extracted
let tel, texto, push_name, location_lat = null, location_lng = null;
// Número da loja que recebeu a mensagem: a API escolhe o estabelecimento por ele (sem isso cai no mais antigo).
let instancia = 'meta';

if (raw.entry) {
  // Direct Meta webhook format
  const value = raw.entry?.[0]?.changes?.[0]?.value;
  const message = value?.messages?.[0];
  if (!message) return [];
  tel = message.from || '';
  const businessNumber = String(value?.metadata?.display_phone_number || '').replace(/\D/g, '');
  if (businessNumber) instancia = businessNumber;
  push_name = value?.contacts?.[0]?.profile?.name || '';
  if (message.type === 'text') {
    texto = (message.text?.body || '').trim();
  } else if (message.type === 'interactive') {
    const ia = message.interactive;
    texto = ia?.button_reply?.id || ia?.list_reply?.id || '';
  } else if (message.type === 'location') {
    location_lat = message.location?.latitude;
    location_lng = message.location?.longitude;
    texto = '__location__';
  }
} else {
  // Pre-extracted from 01-whatsapp-receiver
  tel = raw.tel || raw.from || '';
  texto = (raw.texto || raw.text || '').trim();
  push_name = raw.push_name || '';
  location_lat = raw.location_lat || null;
  location_lng = raw.location_lng || null;
}

if (!tel) return [];
if (!texto && !location_lat) return [];

// texto_original: o que o cliente escreveu, com maiúsculas (observação do item, detalhe do problema).
return [{ json: { tel, texto: texto.toLowerCase(), texto_original: texto, push_name, location_lat, location_lng, instancia } }];

const now = new Date();
const optsTime = { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit', hour12: false };
const horaAtual = now.toLocaleTimeString('pt-BR', optsTime).substring(0, 5);
const diaBR = new Date(now.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const dias = ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sab'];
const diaSemana = dias[diaBR.getDay()];

return [{ json: { ...$json, horaAtual, diaSemana } }];

const apiUrl = ($env.ORDER_HUB_API_URL || 'http://order_hub_api:3333').replace(/\/$/, '');
const headers = { 'Content-Type': 'application/json', 'X-Internal-Token': $env.ORDER_HUB_N8N_INTERNAL_TOKEN || '' };
const { tel, instancia } = $('Calcular Hora').first().json;
const context = await this.helpers.httpRequest({
  method: 'GET',
  url: `${apiUrl}/internal/bot/${encodeURIComponent(tel)}/context`,
  qs: { instance: instancia },
  headers,
  json: true,
});
return [{ json: context }];

const msgData = $('Gravar Pedido e Reserva').first().json;
const { tel, respostas } = msgData;
const msgs = Array.isArray(respostas) ? respostas : [respostas];

const token = $env.WHATSAPP_ACCESS_TOKEN;
const phoneId = $env.WHATSAPP_PHONE_NUMBER_ID;
const version = $env.WHATSAPP_API_VERSION || 'v21.0';
const url = `https://graph.facebook.com/${version}/${phoneId}/messages`;
const headers = { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` };

const buildPayload = (to, msg) => {
  if (typeof msg === 'string') {
    return { messaging_product: 'whatsapp', to, type: 'text', text: { body: msg } };
  }
  if (msg.type === 'buttons') {
    return {
      messaging_product: 'whatsapp', to, type: 'interactive',
      interactive: {
        type: 'button', body: { text: msg.body },
        action: { buttons: msg.buttons.slice(0,3).map(b => ({ type: 'reply', reply: { id: String(b.id), title: String(b.title).slice(0,20) } })) }
      }
    };
  }
  if (msg.type === 'list') {
    return {
      messaging_product: 'whatsapp', to, type: 'interactive',
      interactive: {
        type: 'list', body: { text: msg.body },
        action: { button: msg.button || 'Ver opções', sections: msg.sections }
      }
    };
  }
  if (msg.type === 'location') {
    return { messaging_product: 'whatsapp', to, type: 'location', location: { latitude: msg.latitude, longitude: msg.longitude, name: msg.name || '', address: msg.address || '' } };
  }
  if (msg.type === 'text_menu') {
    return { messaging_product: 'whatsapp', to, type: 'text', text: { body: msg.body } };
  }
  return { messaging_product: 'whatsapp', to, type: 'text', text: { body: typeof msg === 'object' && msg.body ? msg.body : String(msg) } };
};

const sent = [];
for (let i = 0; i < msgs.length; i++) {
  try {
    await this.helpers.httpRequest({ method: 'POST', url, headers, body: JSON.stringify(buildPayload(tel, msgs[i])) });
    sent.push(true);
  } catch(e) { sent.push({ error: e.message }); }
  if (i < msgs.length - 1) await new Promise(r => setTimeout(r, 800));
}
return [{ json: { ok: sent.every(s => s === true), tel, count: msgs.length, sent } }];

const apiUrl = ($env.ORDER_HUB_API_URL || 'http://order_hub_api:3333').replace(/\/$/, '');
const headers = { 'Content-Type': 'application/json', 'X-Internal-Token': $env.ORDER_HUB_N8N_INTERNAL_TOKEN || '' };
const establishmentId = ($('Buscar Dados').first().json.establishment || {}).id;
const data = $json;
await this.helpers.httpRequest({
  method: 'PUT',
  url: `${apiUrl}/internal/bot/${encodeURIComponent(data.tel)}/session`,
  headers,
  body: { establishmentId, state: data.state, cart: data.cart || {}, reservationDraft: data.reservation_temp || {} },
  json: true,
});
return $input.all();

const data = $json;
if (!data.save_customer_name || !data.customer_name_to_save) return [];
return [{ json: { tel: data.tel, customer_name: data.customer_name_to_save } }];

const apiUrl = ($env.ORDER_HUB_API_URL || 'http://order_hub_api:3333').replace(/\/$/, '');
const headers = { 'Content-Type': 'application/json', 'X-Internal-Token': $env.ORDER_HUB_N8N_INTERNAL_TOKEN || '' };
const establishmentId = ($('Buscar Dados').first().json.establishment || {}).id;
await this.helpers.httpRequest({
  method: 'PUT',
  url: `${apiUrl}/internal/bot/${encodeURIComponent($json.tel)}/customer`,
  headers,
  body: { establishmentId, name: $json.customer_name },
  json: true,
});
return [{ json: { saved: true } }];

// Aviso de pedido novo para o WhatsApp da cozinha. Pedido esperando Pix/link de cartão vai marcado
// para não começar antes do pagamento (o painel da cozinha só mostra depois); encomenda vai com o horário.
const fmtBRL = (value) => Number(value || 0).toFixed(2).replace('.', ',');
const localDateTime = (iso) => new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', weekday: 'short', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).format(new Date(iso));
const data = $json;
if (!data.order_saved || !data.kitchen_phone) return [];
const order = data.order || {};

const itemLines = (order.items || [])
  .map((item) => `• *${item.qty}× ${item.name}*` + (item.note ? `\n   📝 _${item.note}_` : ''))
  .join('\n');
const customer = data.customer_name ? `${data.customer_name} (+${data.tel})` : `+${data.tel}`;
const whereLine = order.order_type === 'delivery'
  ? `🛵 *Entrega:* ${order.address || ''}`
  : (order.order_type === 'mesa' ? '🍽️ *Pedido na mesa*' : '🛍️ *Retirada no balcão*');
const whenLine = order.scheduled_for ? `\n📅 *Encomenda para ${localDateTime(order.scheduled_for)}*` : '';
const changeLine = order.change_for ? `\n💵 Levar troco para *R$ ${fmtBRL(order.change_for)}*` : '';
const paymentPendingLine = data.payment_pending ? '\n\n⏳ *Aguardando o pagamento online.* Só comece quando o pedido aparecer no painel da cozinha.' : '';
const feeLine = order.delivery_fee > 0 ? `\n🛵 Taxa de entrega: R$ ${fmtBRL(order.delivery_fee)}` : '';

const msg = `🔔 *Pedido novo chegando!* 🎉\n\n`
  + `🔖 *${order.code || ''}*\n`
  + `👤 ${customer}${whenLine}\n\n`
  + `${itemLines}\n\n`
  + `Subtotal: R$ ${fmtBRL(order.subtotal)}${feeLine}\n`
  + `💰 *Total: R$ ${fmtBRL(order.total)}*\n\n`
  + `${whereLine}\n`
  + `💳 ${order.payment_method || ''}${changeLine}${paymentPendingLine}`;
return [{ json: { instancia: data.instancia, number: data.kitchen_phone, text: msg } }];

const { number, text } = $json;
const token = $env.WHATSAPP_ACCESS_TOKEN;
const phoneId = $env.WHATSAPP_PHONE_NUMBER_ID;
const version = $env.WHATSAPP_API_VERSION || 'v21.0';
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/${version}/${phoneId}/messages`,
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
    body: JSON.stringify({ messaging_product: 'whatsapp', to: number, type: 'text', text: { body: text } })
  });
} catch(e) {}
return [{ json: { ok: true } }];

const data = $json;
if (!data.save_marketing_opt_in || data.marketing_opt_in_value === null || data.marketing_opt_in_value === undefined) return [];
return [{ json: { tel: data.tel, marketing_opt_in: data.marketing_opt_in_value } }];

const data = $json;
if (!data.request_human_handoff) return [];
return [{ json: {
  tel: data.tel,
  customer_name: data.handoff_customer_name || 'cliente'
} }];

const { tel, instancia, customer_name } = $json;
const establishment = $('Buscar Dados').first().json.establishment || {};
const config = $('Buscar Dados').first().json.config || {};
const agentPhone = config['agent_phone'] || '';

const apiUrl = ($env.ORDER_HUB_API_URL || 'http://order_hub_api:3333').replace(/\/$/, '');
const internalToken = $env.ORDER_HUB_N8N_INTERNAL_TOKEN || '';

if (!establishment.id) {
  console.log('[order-hub] Establishment não resolvido — não é possível solicitar atendimento humano');
  return [{ json: { ok: false, skip: true, instancia, agentPhone, tel, customer_name } }];
}

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${apiUrl}/conversations/${tel}/request-human`,
    headers: { 'Content-Type': 'application/json', 'X-Internal-Token': internalToken },
    body: JSON.stringify({ establishmentId: establishment.id, customerName: customer_name || 'cliente' })
  });
} catch (e) {
  console.log('[order-hub] Erro ao solicitar atendimento humano:', e.message);
}

return [{ json: { ok: true, instancia, agentPhone, customer_name, tel } }];

const { agentPhone, customer_name, tel } = $json;
if (!agentPhone) return [{ json: { done: true } }];
const token = $env.WHATSAPP_ACCESS_TOKEN;
const phoneId = $env.WHATSAPP_PHONE_NUMBER_ID;
const version = $env.WHATSAPP_API_VERSION || 'v21.0';
const webUrl = ($env.ORDER_HUB_WEB_PUBLIC_URL || '').replace(/\/$/, '');
const digits = String(tel || '').replace(/\D/g, '');
const text = '🙋 *Tem cliente chamando a equipe!*\n\n'
  + `👤 *${customer_name || 'Cliente sem nome'}*\n`
  + `📱 +${digits}\n\n`
  + (webUrl
    ? `É só abrir a conversa e assumir por aqui 👇\n${webUrl}/conversations`
    : `⚠️ O painel não está configurado. Responda direto: wa.me/${digits}`);
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/${version}/${phoneId}/messages`,
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
    body: JSON.stringify({ messaging_product: 'whatsapp', to: agentPhone, type: 'text', text: { body: text } })
  });
} catch (e) {}
return [{ json: { done: true } }];

const tel = $('Calcular Hora').first().json.tel;
const texto = $('Calcular Hora').first().json.texto;
const establishment = $json.establishment || {};

const apiUrl = ($env.ORDER_HUB_API_URL || 'http://order_hub_api:3333').replace(/\/$/, '');
const internalToken = $env.ORDER_HUB_N8N_INTERNAL_TOKEN || '';

if (!establishment.id) return [{ json: { skipped: true } }];

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${apiUrl}/conversations/${tel}/messages`,
    headers: { 'Content-Type': 'application/json', 'X-Internal-Token': internalToken },
    body: JSON.stringify({
      establishmentId: establishment.id,
      direction: 'inbound',
      sender: 'customer',
      type: 'text',
      content: texto,
    })
  });
} catch (e) {
  console.log('[order-hub] Erro ao registrar mensagem inbound:', e.message);
}

return [{ json: { logged: true } }];

const msgData = $('Gravar Pedido e Reserva').first().json;
const { tel, respostas, state, cart, reservation_temp } = msgData;
const establishment = $('Buscar Dados').first().json.establishment || {};
const msgs = Array.isArray(respostas) ? respostas : [respostas];

const apiUrl = ($env.ORDER_HUB_API_URL || 'http://order_hub_api:3333').replace(/\/$/, '');
const internalToken = $env.ORDER_HUB_N8N_INTERNAL_TOKEN || '';

function contentOf(msg) {
  if (typeof msg === 'string') return msg;
  if (msg && typeof msg === 'object') return msg.body || JSON.stringify(msg);
  return String(msg);
}

if (establishment.id) {
  for (let i = 0; i < msgs.length; i++) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${apiUrl}/conversations/${tel}/messages`,
        headers: { 'Content-Type': 'application/json', 'X-Internal-Token': internalToken },
        body: JSON.stringify({
          establishmentId: establishment.id,
          direction: 'outbound',
          sender: 'bot',
          type: 'text',
          content: contentOf(msgs[i]),
          currentState: state,
          context: { cart, reservation_temp },
        })
      });
    } catch (e) {
      console.log('[order-hub] Erro ao registrar mensagem outbound:', e.message);
    }
  }
}

return [{ json: { logged: true } }];

// O cliente só lê "confirmado" depois que a API gravou. Se a gravação falha, a sessão volta ao
// passo anterior com o carrinho intacto e a resposta vira um aviso honesto.
const routed = $('Rotear e Responder').first().json;
const context = $('Buscar Dados').first().json;
const previousSession = context.session || {};
const establishmentId = (context.establishment || {}).id;
const apiUrl = ($env.ORDER_HUB_API_URL || 'http://order_hub_api:3333').replace(/\/$/, '');
const headers = { 'Content-Type': 'application/json', 'X-Internal-Token': $env.ORDER_HUB_N8N_INTERNAL_TOKEN || '' };
const out = { ...routed, order_saved: false, reservation_saved: false, issue_saved: false, partial_answer_saved: false };

const MSG_ORDER_FAILED = '😕 *Poxa, não consegui registrar seu pedido agora.*\n\nFica tranquilo(a): seu carrinho continua salvo! Responda de novo a última pergunta para tentar outra vez, ou digite *atendente* que alguém da equipe te ajuda. 🧡';
const MSG_SLOT_TAKEN = '😕 *Ih, esse horário acabou de ser preenchido!*\n\nResponda *sim* que eu te mostro os horários que ainda estão livres. 🕒';
const MSG_RESERVATION_FAILED = '😕 *Não consegui registrar sua reserva agora.*\n\nTenta de novo daqui a pouquinho ou digite *atendente* que a gente resolve pra você. 🧡';
const MSG_ISSUE_FAILED = '😕 *Não consegui registrar o que aconteceu agora.*\n\nPode tentar de novo daqui a pouquinho? Se preferir, digite *atendente* que alguém da equipe fala com você.';
const MSG_PARTIAL_FAILED = '😕 *Não consegui registrar sua resposta agora.*\n\nPode mandar de novo daqui a pouquinho? Se preferir, digite *atendente* que alguém da equipe te ajuda.';
const MSG_PARTIAL_REFUND = (amount) => `💸 Como o pedido já estava pago, a equipe vai devolver *${amount}* pra você. Qualquer dúvida, é só chamar!`;
const brl = (value) => Number(value || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
// Pagamento online (Pix/link de cartão) gerado pela API na conta do restaurante: vai em mensagens
// separadas, com o copia-e-cola sozinho para o cliente copiar com um toque.
const MSG_PIX = (code, amount, minutes) => `🔷 *Agora é só pagar o Pix do pedido ${code}!*\n\n💰 Valor: *${amount}*\n\nCopie o código da próxima mensagem e cole no app do seu banco, na opção _Pix copia e cola_. Ele vale por *${minutes} min*.\n\n👨‍🍳 Assim que o pagamento cair, seu pedido vai direto pra cozinha!`;
const MSG_PIX_TICKET = (url) => `📱 Se preferir, abra o QR code por aqui: ${url}`;
const MSG_CARD_LINK = (code, amount, url, minutes) => `💳 *Agora é só pagar o pedido ${code} no cartão!*\n\n💰 Valor: *${amount}*\n👉 ${url}\n\nO link vale por *${minutes} min*. Assim que o pagamento for aprovado, seu pedido vai direto pra cozinha! 👨‍🍳`;
const MSG_PAYMENT_UNAVAILABLE = (code) => `😕 Não consegui gerar o pagamento online do pedido *${code}* agora.\n\nMas fica tranquilo(a): o pedido está anotado e você paga na entrega ou na retirada. 😉`;
const MSG_NO_TABLE = '😕 *Poxa, não temos mesa livre nesse horário.*\n\nMe manda outra data e horário (ex: _sábado às 21h para 4 pessoas_) que eu vejo pra você!';

const errorText = (error) => {
  try { return JSON.stringify(error.response?.body ?? error.cause?.response?.body ?? error.description ?? error.message ?? error); }
  catch (e) { return String(error && error.message); }
};
const localTime = (iso) => new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' }).format(new Date(iso));
const appendToConfirmation = (marker, line) => {
  const index = out.respostas.findIndex((message) => typeof message === 'string' && message.includes(marker));
  if (index >= 0) out.respostas[index] = out.respostas[index] + line;
};
const rollback = (state, cart) => {
  out.state = state;
  out.cart = cart;
  out.save_order = false;
  out.save_reservation = false;
};

if (routed.save_order && routed.order) {
  const order = routed.order;
  try {
    const created = await this.helpers.httpRequest({
      method: 'POST',
      url: `${apiUrl}/internal/bot/${encodeURIComponent(routed.tel)}/orders`,
      headers,
      json: true,
      body: {
        establishmentId,
        customerName: order.customer_name || undefined,
        code: order.code,
        orderType: order.order_type,
        items: (order.items || []).map((item) => ({ productId: item.id, quantity: item.qty, notes: item.note || undefined })),
        paymentMethod: order.payment_method,
        changeFor: order.change_for ?? undefined,
        payments: (order.payments || []).map((payment) => ({
          method: payment.method,
          amount: payment.amount,
          changeFor: payment.change_for ?? undefined,
          splitLabel: payment.split_label ?? undefined,
        })),
        deliveryFee: order.delivery_fee || undefined,
        address: order.address || undefined,
        mapsLink: order.maps_link || undefined,
        scheduledFor: order.scheduled_for || undefined,
      },
    });
    out.order_saved = true;
    if (created && created.estimatedAt && !order.scheduled_for) {
      const label = order.order_type === 'delivery' ? 'Previsão de entrega' : 'Previsão para ficar pronto';
      appendToConfirmation('Pedido confirmado', `\n\n⏱️ *${label}: ${localTime(created.estimatedAt)}* (cerca de ${created.estimatedMinutes} min)`);
    }
    const payment = created && created.payment;
    if (payment && payment.status === 'created') {
      // Cozinha só fica sabendo quando o pagamento cair (a API avisa).
      out.payment_pending = true;
      out.respostas = Array.isArray(out.respostas) ? out.respostas : [];
      if (payment.kind === 'pix' && payment.pixCopyPaste) {
        out.respostas.push(MSG_PIX(order.code, brl(payment.amount), payment.expirationMinutes));
        out.respostas.push(payment.pixCopyPaste);
        if (payment.ticketUrl) out.respostas.push(MSG_PIX_TICKET(payment.ticketUrl));
      } else if (payment.paymentUrl) {
        out.respostas.push(MSG_CARD_LINK(order.code, brl(payment.amount), payment.paymentUrl, payment.expirationMinutes));
      }
    } else if (payment && payment.status === 'unavailable') {
      out.respostas = Array.isArray(out.respostas) ? out.respostas : [];
      out.respostas.push(MSG_PAYMENT_UNAVAILABLE(order.code));
    }
  } catch (error) {
    const previousCart = previousSession.cart || {};
    if (errorText(error).includes('agenda_slot_unavailable')) {
      rollback('confirming', { ...previousCart, scheduled_time: '', scheduled_date: '' });
      out.respostas = [MSG_SLOT_TAKEN];
    } else {
      rollback(previousSession.state || 'start', previousCart);
      out.respostas = [MSG_ORDER_FAILED];
    }
    out.save_marketing_opt_in = false;
  }
}

if (routed.save_reservation && routed.reservation) {
  const reservation = routed.reservation;
  try {
    const created = await this.helpers.httpRequest({
      method: 'POST',
      url: `${apiUrl}/internal/bot/${encodeURIComponent(routed.tel)}/reservations`,
      headers,
      json: true,
      body: {
        establishmentId,
        customerName: reservation.customer_name || undefined,
        code: reservation.code,
        date: reservation.date,
        time: reservation.time,
        partySize: reservation.party_size,
      },
    });
    out.reservation_saved = true;
    if (created && created.tableNumber) appendToConfirmation('Reserva confirmada', `\n🪑 Mesa ${created.tableNumber}`);
  } catch (error) {
    const text = errorText(error);
    rollback(text.includes('agenda_no_table_available') ? 'reserving' : (previousSession.state || 'start'), previousSession.cart || {});
    out.reservation_temp = {};
    out.respostas = [text.includes('agenda_no_table_available') ? MSG_NO_TABLE : MSG_RESERVATION_FAILED];
  }
}

// Problema relatado pelo cliente: vira métrica nos Relatórios do painel.
if (routed.save_issue && routed.issue) {
  const issue = routed.issue;
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${apiUrl}/internal/bot/${encodeURIComponent(routed.tel)}/issues`,
      headers,
      json: true,
      body: {
        establishmentId,
        orderCode: issue.order_code || undefined,
        category: issue.category,
        description: issue.description || undefined,
      },
    });
    out.issue_saved = true;
  } catch (error) {
    out.respostas = [MSG_ISSUE_FAILED];
  }
}

// Resposta SIM/NÃO à confirmação parcial pedida pela equipe no painel.
if (routed.save_partial_answer && routed.partial_answer) {
  try {
    const answer = await this.helpers.httpRequest({
      method: 'POST',
      url: `${apiUrl}/internal/bot/${encodeURIComponent(routed.tel)}/partial-confirmation`,
      headers,
      json: true,
      body: { establishmentId, accept: !!routed.partial_answer.accept },
    });
    out.partial_answer_saved = true;
    if (answer && answer.refundDue > 0) out.respostas.push(MSG_PARTIAL_REFUND(brl(answer.refundDue)));
  } catch (error) {
    out.respostas = [MSG_PARTIAL_FAILED];
  }
}

return [{ json: out }];
